NO_ASCII_REGEX = re.compile(r"[^\x00-\x7F]+")
NO_SPECIAL_REGEX = re.compile(r"[^\w.@+_-]+", re.UNICODE)


class UserProtocol(Protocol):
    id: int
    username: str
    is_active: bool | Callable[[], bool]
    is_authenticated: bool | Callable[[], bool]

    # Set in BaseAuth.pipeline
